WITH by_dimension AS (SELECT s.city, src.status, COUNT(*) AS rows_total, MAX(src.shipping_fee) AS max_shipping_fee, GROUPING_ID() AS grouping_level FROM orders src INNER JOIN stores s ON src.store_id = s.id GROUP BY CUBE (s.city, src.status)) SELECT city, rows_total, grouping_level, CASE WHEN city RLIKE '^(Tokyo|Singapore)$' THEN 'OTHER_ZONE' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS city_zone FROM by_dimension ORDER BY rows_total DESC
